WITH with_dims AS (SELECT s.id, s.customer_id, s.plan, s.monthly_fee, b.age FROM subscriptions s LEFT JOIN customers b ON s.customer_id = b.id WHERE b.name LIKE 'D%') SELECT s.id, s.customer_id, s.plan, s.monthly_fee, s.age, (SELECT MAX(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM with_dims s ORDER BY max_subscription_monthly_fee, age;
